        card("D. Grammatical structure", "When using benefactive verbs in a sentence, the doer comes from Set 2 and the beneficiary (the focus) from Set 1. The structure is: benefactive verb, doer with a Set 2 marker, object with a Set 2 marker, beneficiary with a Set 1 marker.", tables=[table(["Benefactive verb", "Doer (Set 2)", "Object (Set 2)", "Beneficiary (Set 1)"], _GS, say=[])]),
        card("The sentences from the reading presentation", "The book asks you to identify the benefactive verbs and translate the sentences (the book’s translations).", examples=passage(_RS)),
