        card("F. Structure with a demonstrative pronoun as the doer", "Verb, beneficiary, doer (the demonstrative), marker, object.", tables=[table(["Benefactive verb", "Beneficiary", "Doer", "Marker", "Object"], _S3, say=[])], examples=passage(_SS)),
