        + [F("Ang ___ ng pamahalaan ay agarang paghatid ng pagkain. (priorities)", "prayoridad", ["serbisyo", "aksiyon"], "prayoridad."), F("Pangalawa, ___ nang pansamantalang panuluyan. (giving)", "pagbibigay", ["pagbalik", "pagtatayo"], "pagbibigay."), F("Naka-alerto ang Philippine ___. (Coastguard)", "Coastguard", ["Army", "Navy Hospital"], "Coastguard."), F("Maging alerto mula sa posibleng storm ___. (surge)", "surge", ["signal", "kit"], "surge.")]
